// Период опроса в секундах
const T = 5;

// Допустимые диапазоны датчиков
const RANGES = {
    s1: [0,300],
    s2: [0, 1],
    s3: [0, 1]
};

// Получаем текст журнала
const text = String(msg.payload).replace(/^\uFEFF/, '');
const sql = [];

// Обрабатываем строки
text.split(/\r?\n/).forEach(raw => {
    const line = raw.trim();
    if (!line) return;

    const parts = line.split(/\s+/);
    const kind = parts[0];

    // Получаем параметры вида имя=значение
    const f = {};

    parts.slice(1).forEach(p => {
        const index = p.indexOf('=');

        if (index > 0) {
            f[p.slice(0, index)] = p.slice(index + 1);
        }
    })

    // Проверяем номер измерения
    if (!/^\d+$/.test(f.n || '')) return;

    const n = Number(f.n);
    if (n < 1 || !Number.isSafeInteger(n)) return;

    const t = n * T;

    // Определяем режим измерения
    const mode = f.mode === 'TEST' ? 'TEST' : 'AUTO';

    // Обработка показаний датчиков
    if (kind === 'DATA') {
        ['s1', 's2', 's3'].forEach(s => {
            const rawValue = f[s];
            const validNumber = rawValue !== undefined && /^-?\d+(\.\d+)?$/.test(rawValue);

            const v = validNumber ? Number(rawValue) : NaN;

            // Сохраняем корректное числовое показание
            if (Number.isFinite(v)) {
                sql.push(
                    `INSERT INTO readings(n,t_s,sensor,value,mode) VALUES(${n},${t},'${s}',${v},'${mode}');`
                );
            }

            // Проверяем неисправность датчика
            const [min, max] = RANGES[s];

            if (!Number.isFinite(v) || v < min || v > max) {
                sql.push(
                    `INSERT INTO events(n,t_s,type,message,mode) VALUES(${n},${t},'FAULT','датчик ${s} вне диапазона','${mode}');`
                );
            }
        });
    }

    // Обработка событий Arduino
    else if (kind === 'EVENT') {
        if (f.type === 'THRESHOLD' || f.type === 'NORMAL') {
            sql.push(
                `INSERT INTO events(n,t_s,type,message,mode) VALUES(${n},${t},'${f.type}',NULL,'${mode}');`
            );
        }
    }

});

// Если подходящих записей нет, ничего не загружаем
if (sql.length === 0) {
    node.warn("В журнале нед данных для загрузки");
    return [null, null];
}

// Формируем SQL-файл
const result = 'BEGIN;\n' + 'DELETE FROM readings;\n' + 'DELETE FROM events;\n' + "DELETE FROM sqlite_sequence WHERE name IN ('readings','events');\n" + sql.join('\n') + '\nCOMMIT;\n';

// Передаем SQL через второй выход
return [null, {payload: result}];
